import csv
from datetime import datetime, timedelta
from collections import defaultdict

meta = {}
with open('dataset/sensor_metadata.csv') as f:
    for row in csv.DictReader(f):
        if not row['sensor_id']: continue
        meta[row['sensor_id']] = {
            'subsystem': row['subsystem'],
            'lo': float(row['normal_min']), 'hi': float(row['normal_max']),
            'delay': int(row['response_delay_minutes']),
        }

readings = defaultdict(list)
for fn in ['sensors_01.csv','sensors_02.csv','sensors_03.csv']:
    with open(f'dataset/{fn}') as f:
        for row in csv.DictReader(f):
            sid = row['sensor_id']
            t = datetime.fromisoformat(row['timestamp']) - timedelta(hours=meta[sid]['offset'] if 'offset' in meta[sid] else 0)
            readings[sid].append((t, float(row['value'])))

# redo with offset properly
meta2 = {}
with open('dataset/sensor_metadata.csv') as f:
    for row in csv.DictReader(f):
        if not row['sensor_id']: continue
        meta2[row['sensor_id']] = int(row['logger_utc_offset_hours'])
readings = defaultdict(list)
for fn in ['sensors_01.csv','sensors_02.csv','sensors_03.csv']:
    with open(f'dataset/{fn}') as f:
        for row in csv.DictReader(f):
            sid = row['sensor_id']
            t = datetime.fromisoformat(row['timestamp']) - timedelta(hours=meta2[sid])
            readings[sid].append((t, float(row['value'])))
for sid in readings: readings[sid].sort()

# Find all out-of-range excursions (runs of consecutive OOR readings)
for sid, m in meta.items():
    vals = readings[sid]
    runs = []
    cur = None
    for t, v in vals:
        oor = v < m['lo'] or v > m['hi']
        if oor:
            if cur is None: cur = [t, t, 1]
            else: cur[1] = t; cur[2] += 1
        else:
            if cur: runs.append(cur); cur = None
    if cur: runs.append(cur)
    print(f"{sid:18s} {m['subsystem']:12s} delay={m['delay']}min  runs={len(runs)}")
    for r in runs[:8]:
        print(f"    OOR {r[0]} -> {r[1]}  ({r[2]} pts)")
    if len(runs) > 8: print(f"    ... {len(runs)-8} more runs")
EOF

